import os

for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in (".git", "node_modules")]
    for f in files:
        if f.lower().endswith(".pptx"):
            print(os.path.join(root, f))

import os, glob

base = "workspace/unpacked"
print("=== SLIDE FILES ===")
for f in sorted(glob.glob(os.path.join(base, "ppt/slides/slide*.xml"))):
    print(os.path.basename(f))

print("\n=== SLIDE RELS FILES ===")
for f in sorted(glob.glob(os.path.join(base, "ppt/slides/_rels/*.rels"))):
    print(os.path.basename(f))

print("\n=== SLIDE LAYOUTS ===")
for f in sorted(glob.glob(os.path.join(base, "ppt/slideLayouts/*.xml"))):
    print(os.path.basename(f))

print("\n=== NOTES SLIDES ===")
for f in sorted(glob.glob(os.path.join(base, "ppt/notesSlides/*.xml"))):
    print(os.path.basename(f))

for name in ["ppt/presentation.xml", "ppt/_rels/presentation.xml.rels", "[Content_Types].xml", "docProps/app.xml"]:
    p = os.path.join(base, name)
    print(f"\n=== {name} ===")
    if os.path.exists(p):
        with open(p, "r", encoding="utf-8") as fh:
            print(fh.read())
    else:
        print("(missing)")

